import SwiftUI
struct CandidateDetailView: View { let candidate: Candidate; var body: some View { List { Section("Decision"){LabeledContent("Pair",value:candidate.pair);LabeledContent("Decision",value:candidate.decision ?? "WATCH");LabeledContent("Reason",value:candidate.reason ?? "—")} Section("Signal"){LabeledContent("Score",value:String(format:"%.0f",candidate.score ?? 0));LabeledContent("Displacement",value:String(format:"%.2f%%",candidate.displacement_pct ?? 0));LabeledContent("Extension",value:String(format:"%.2f%%",candidate.extension_pct ?? 0))} } .navigationTitle(candidate.pair) } }
